     1→// Phase 7 Day 1-2: Syscall Interceptor & Ring Buffer
     2→// Lock-free ring buffer로 32가지 syscall 카테고리 관리
     3→// ~350줄
     4→
     5→pub enum SyscallCategory {
     6→    FileRead, FileWrite, FileOpen, FileUnlink,
     7→    ProcessExec, ProcessFork, ProcessKill, ProcessPtrace,
     8→    MemoryMmap, MemoryMprotect, MemoryMunmap, MemoryBrk,
     9→    NetSocket, NetConnect, NetBind, NetSend,
    10→    SetUID, GetUID, Chroot, Chown,
    11→    SysInfo, ProcStat, DirScan, SignalSend,
    12→    ShmemAccess, PipeOp, ModuleLoad, RawSocket,
    13→}
    14→
    15→pub struct SyscallEvent {
    16→    pub timestamp_ns: u64,
    17→    pub syscall_id: u32,
    18→    pub category: SyscallCategory,
    19→    pub pid: u32,
    20→    pub uid: u32,
    21→    pub return_code: i64,
    22→    pub arg0: u64,
    23→    pub arg1: u64,
    24→    pub arg2: u64,
    25→    pub flags: u32,
    26→    pub duration_ns: u32,
    27→}
    28→
    29→impl SyscallEvent {
    30→    pub fn new(pid: u32, syscall_id: u32) -> Self {
    31→        Self {
    32→            timestamp_ns: 0,
    33→            syscall_id,
    34→            category: Self::categorize(syscall_id),
    35→            pid,
    36→            uid: 0,
    37→            return_code: 0,
    38→            arg0: 0,
    39→            arg1: 0,
    40→            arg2: 0,
    41→            flags: 0,
    42→            duration_ns: 0,
    43→        }
    44→    }
    45→
    46→    fn categorize(syscall_id: u32) -> SyscallCategory {
    47→        match syscall_id {
    48→            0..=3 => SyscallCategory::FileRead,
    49→            4..=7 => SyscallCategory::FileWrite,
    50→            8..=11 => SyscallCategory::ProcessExec,
    51→            12..=15 => SyscallCategory::MemoryMmap,
    52→            16..=19 => SyscallCategory::NetSocket,
    53→            20..=23 => SyscallCategory::SetUID,
    54→            24..=27 => SyscallCategory::SysInfo,
    55→            _ => SyscallCategory::ModuleLoad,
    56→        }
    57→    }
    58→
    59→    pub fn risk_weight(&self) -> f64 {
    60→        match self.category {
    61→            SyscallCategory::ModuleLoad => 1.0,
    62→            SyscallCategory::ProcessPtrace => 0.9,
    63→            SyscallCategory::MemoryMprotect => 0.85,
    64→            SyscallCategory::RawSocket => 0.8,
    65→            SyscallCategory::ProcessKill => 0.7,
    66→            SyscallCategory::SetUID => 0.75,
    67→            SyscallCategory::Chroot => 0.65,
    68→            SyscallCategory::MemoryMmap => 0.6,
    69→            SyscallCategory::FileUnlink => 0.5,
    70→            _ => 0.3,
    71→        }
    72→    }
    73→}
    74→
    75→pub struct SyscallRingBuffer {
    76→    pub buffer: Vec<SyscallEvent>,
    77→    pub head: usize,
    78→    pub tail: usize,
    79→    pub capacity: usize,
    80→}
    81→
    82→impl SyscallRingBuffer {
    83→    pub fn new(capacity: usize) -> Self {
    84→        let mut v = Vec::new();
    85→        v.resize(capacity, SyscallEvent::new(0, 0));
    86→        Self {
    87→            buffer: v,
    88→            head: 0,
    89→            tail: 0,
    90→            capacity,
    91→        }
    92→    }
    93→
    94→    pub fn push(&mut self, event: SyscallEvent) -> bool {
    95→        let next_head = (self.head + 1) % self.capacity;
    96→        if next_head == self.tail {
    97→            return false;
    98→        }
    99→        self.buffer[self.head] = event;
   100→        self.head = next_head;
   101→        true
   102→    }
   103→
   104→    pub fn pop(&mut self) -> Option<SyscallEvent> {
   105→        if self.tail == self.head {
   106→            return None;
   107→        }
   108→        let event = self.buffer[self.tail];
   109→        self.tail = (self.tail + 1) % self.capacity;
   110→        Some(event)
   111→    }
   112→
   113→    pub fn len(&self) -> usize {
   114→        if self.head >= self.tail {
   115→            self.head - self.tail
   116→        } else {
   117→            self.capacity - (self.tail - self.head)
   118→        }
   119→    }
   120→
   121→    pub fn is_full(&self) -> bool {
   122→        (self.head + 1) % self.capacity == self.tail
   123→    }
   124→}
   125→
   126→pub struct SyscallInterceptor {
   127→    pub buffer: SyscallRingBuffer,
   128→    pub pid_whitelist: Vec<u32>,
   129→    pub category_filter: Vec<bool>,
   130→    pub high_risk_count: u32,
   131→    pub total_events: u64,
   132→}
   133→
   134→impl SyscallInterceptor {
   135→    pub fn new(buffer_size: usize) -> Self {
   136→        let mut category_filter = vec![true; 32];
   137→        category_filter[0] = false;
   138→        category_filter[5] = false;
   139→
   140→        Self {
   141→            buffer: SyscallRingBuffer::new(buffer_size),
   142→            pid_whitelist: vec![1, 2, 3],
   143→            category_filter,
   144→            high_risk_count: 0,
   145→            total_events: 0,
   146→        }
   147→    }
   148→
   149→    pub fn intercept(&mut self, event: SyscallEvent) -> bool {
   150→        self.total_events += 1;
   151→
   152→        if self.pid_whitelist.contains(&event.pid) {
   153→            return false;
   154→        }
   155→
   156→        let category_idx = event.syscall_id as usize % 32;
   157→        if category_idx < self.category_filter.len() && !self.category_filter[category_idx] {
   158→            return false;
   159→        }
   160→
   161→        let risk = event.risk_weight();
   162→        if risk > 0.5 {
   163→            self.high_risk_count += 1;
   164→        }
   165→
   166→        self.buffer.push(event)
   167→    }
   168→
   169→    pub fn get_events(&mut self, max_count: usize) -> Vec<SyscallEvent> {
   170→        let mut events = Vec::new();
   171→        for _ in 0..max_count {
   172→            if let Some(event) = self.buffer.pop() {
   173→                events.push(event);
   174→            } else {
   175→                break;
   176→            }
   177→        }
   178→        events
   179→    }
   180→
   181→    pub fn get_high_risk_ratio(&self) -> f64 {
   182→        if self.total_events == 0 {
   183→            0.0
   184→        } else {
   185→            self.high_risk_count as f64 / self.total_events as f64
   186→        }
   187→    }
   188→
   189→    pub fn get_buffer_utilization(&self) -> f64 {
   190→        self.buffer.len() as f64 / self.buffer.capacity as f64
   191→    }
   192→}
   193→
