     1→// Phase 7 Day 3-4: Behavioral Analyzer
     2→// N-gram 이상치 감지 및 16차원 특성 벡터 생성
     3→// ~400줄
     4→
     5→use std::collections::HashMap;
     6→
     7→pub use super::syscall_interceptor::{SyscallEvent, SyscallCategory};
     8→
     9→// ========== Feature Vector (16차원) ==========
    10→
    11→pub struct SyscallFeatureVector {
    12→    // D0-D4: 카테고리 빈도 (5가지)
    13→    pub file_io_rate: f64,
    14→    pub process_ctrl_rate: f64,
    15→    pub memory_manip_rate: f64,
    16→    pub network_rate: f64,
    17→    pub privilege_rate: f64,
    18→
    19→    // D5-D9: N-gram 이상치 (5가지)
    20→    pub bigram_anomaly: f64,
    21→    pub trigram_anomaly: f64,
    22→    pub fourgram_anomaly: f64,
    23→    pub sequence_entropy: f64,
    24→    pub repetition_factor: f64,
    25→
    26→    // D10-D12: 타이밍 (3가지)
    27→    pub burst_intensity: f64,
    28→    pub avg_duration_normalized: f64,
    29→    pub timing_variance: f64,
    30→
    31→    // D13-D15: 컨텍스트 (3가지)
    32→    pub privilege_level: f64,
    33→    pub high_risk_syscall_count: f64,
    34→    pub return_error_rate: f64,
    35→}
    36→
    37→impl SyscallFeatureVector {
    38→    pub fn new() -> Self {
    39→        Self {
    40→            file_io_rate: 0.0,
    41→            process_ctrl_rate: 0.0,
    42→            memory_manip_rate: 0.0,
    43→            network_rate: 0.0,
    44→            privilege_rate: 0.0,
    45→
    46→            bigram_anomaly: 0.0,
    47→            trigram_anomaly: 0.0,
    48→            fourgram_anomaly: 0.0,
    49→            sequence_entropy: 0.0,
    50→            repetition_factor: 0.0,
    51→
    52→            burst_intensity: 0.0,
    53→            avg_duration_normalized: 0.0,
    54→            timing_variance: 0.0,
    55→
    56→            privilege_level: 0.0,
    57→            high_risk_syscall_count: 0.0,
    58→            return_error_rate: 0.0,
    59→        }
    60→    }
    61→
    62→    pub fn to_vector(&self) -> Vec<f64> {
    63→        vec![
    64→            self.file_io_rate,
    65→            self.process_ctrl_rate,
    66→            self.memory_manip_rate,
    67→            self.network_rate,
    68→            self.privilege_rate,
    69→            self.bigram_anomaly,
    70→            self.trigram_anomaly,
    71→            self.fourgram_anomaly,
    72→            self.sequence_entropy,
    73→            self.repetition_factor,
    74→            self.burst_intensity,
    75→            self.avg_duration_normalized,
    76→            self.timing_variance,
