   174→// ========== Behavioral Analyzer ==========
   175→
   176→pub struct BehavioralAnalyzer {
   177→    pub ngram_extractor: NgramExtractor,
   178→    pub event_history: Vec<SyscallEvent>,
   179→    pub max_history: usize,
   180→}
   181→
   182→impl BehavioralAnalyzer {
   183→    pub fn new() -> Self {
   184→        Self {
   185→            ngram_extractor: NgramExtractor::new(),
   186→            event_history: Vec::new(),
   187→            max_history: 1000,
   188→        }
   189→    }
   190→
   191→    pub fn add_event(&mut self, event: SyscallEvent) {
   192→        self.event_history.push(event);
   193→        if self.event_history.len() > self.max_history {
   194→            self.event_history.remove(0);
   195→        }
   196→
   197→        // N-gram 추출
   198→        self.ngram_extractor
   199→            .add_syscall(event.pid, event.syscall_id as u8);
   200→    }
   201→
   202→    pub fn compute_features(&self, pid: u32) -> SyscallFeatureVector {
   203→        let mut features = SyscallFeatureVector::new();
   204→
   205→        // D0-D4: 카테고리 빈도
   206→        let mut cat_counts = [0u32; 5];
   207→        let mut total_count = 0u32;
   208→        let mut high_risk = 0u32;
   209→        let mut error_count = 0u32;
   210→
   211→        for event in &self.event_history {
   212→            if event.pid != pid {
   213→                continue;
   214→            }
   215→
   216→            total_count += 1;
   217→
   218→            // 카테고리 분류
   219→            let cat_idx = match event.category {
   220→                SyscallCategory::FileRead | SyscallCategory::FileWrite
   221→                | SyscallCategory::FileOpen | SyscallCategory::FileUnlink => 0,
   222→                SyscallCategory::ProcessExec | SyscallCategory::ProcessFork
   223→                | SyscallCategory::ProcessKill | SyscallCategory::ProcessPtrace => 1,
   224→                SyscallCategory::MemoryMmap | SyscallCategory::MemoryMprotect
   225→                | SyscallCategory::MemoryMunmap | SyscallCategory::MemoryBrk => 2,
   226→                SyscallCategory::NetSocket | SyscallCategory::NetConnect
   227→                | SyscallCategory::NetBind | SyscallCategory::NetSend => 3,
   228→                _ => 4,
   229→            };
   230→
   231→            cat_counts[cat_idx] += 1;
   232→
   233→            if event.risk_weight() > 0.5 {
   234→                high_risk += 1;
   235→            }
   236→
   237→            if event.return_code < 0 {
   238→                error_count += 1;
   239→            }
   240→        }
   241→
   242→        if total_count > 0 {
   243→            features.file_io_rate = cat_counts[0] as f64 / total_count as f64;
   244→            features.process_ctrl_rate = cat_counts[1] as f64 / total_count as f64;
   245→            features.memory_manip_rate = cat_counts[2] as f64 / total_count as f64;
   246→            features.network_rate = cat_counts[3] as f64 / total_count as f64;
   247→            features.privilege_rate = cat_counts[4] as f64 / total_count as f64;
   248→
   249→            features.high_risk_syscall_count = high_risk as f64 / total_count as f64;
   250→            features.return_error_rate = error_count as f64 / total_count as f64;
   251→        }
   252→
   253→        // D5-D9: N-gram 이상치
   254→        if let Some(window) = self.ngram_extractor.per_pid_windows.get(&pid) {
   255→            if window.len() >= 2 {
   256→                let bigram = vec![window[window.len() - 2], window[window.len() - 1]];
   257→                features.bigram_anomaly = self.ngram_extractor.get_anomaly_score(&bigram);
   258→            }
   259→
   260→            if window.len() >= 3 {
   261→                let trigram =
   262→                    vec![window[window.len() - 3], window[window.len() - 2], window[window.len() - 1]];
   263→                features.trigram_anomaly = self.ngram_extractor.get_anomaly_score(&trigram);
   264→            }
   265→
   266→            if window.len() >= 4 {
   267→                let fourgram = vec![
   268→                    window[window.len() - 4],
   269→                    window[window.len() - 3],
   270→                    window[window.len() - 2],
   271→                    window[window.len() - 1],
   272→                ];
   273→                features.fourgram_anomaly = self.ngram_extractor.get_anomaly_score(&fourgram);
   274→            }
   275→
   276→            features.sequence_entropy = NgramExtractor::compute_entropy(pid, &self.ngram_extractor);
   277→        }
   278→
   279→        // D10-D12: 타이밍 (간단한 모의)
   280→        features.burst_intensity = (high_risk as f64 / 10.0).min(1.0);
   281→        features.avg_duration_normalized = 0.5;  // Mock
   282→        features.timing_variance = 0.3;  // Mock
   283→
   284→        // D13-D15: 컨텍스트
   285→        features.privilege_level = 0.5;  // Mock (0=user, 1=root)
   286→        features.repetition_factor =
   287→            (self.ngram_extractor.ngram_counts.len() as f64 / total_count.max(1) as f64).min(1.0);
   288→
   289→        features
   290→    }
   291→
   292→    pub fn get_anomaly_score(&self, pid: u32) -> f64 {
   293→        let features = self.compute_features(pid);
   294→        let vec = features.to_vector();
   295→
   296→        // 16차원 이상치 점수 (간단한 평균)
   297→        let sum: f64 = vec.iter().sum();
   298→        (sum / 16.0).min(1.0)
   299→    }
   300→}
