     1→// Phase 7 Day 7: Response Engine
     2→// 위협에 대한 자동 대응 및 정책 기반 의사결정
     3→// ~300줄
     4→
     5→pub use super::threat_classifier::{ThreatType, ClassificationResult};
     6→
     7→// ========== Alert Severity ==========
     8→
     9→#[derive(Clone, Copy, Debug)]
    10→pub enum AlertSeverity {
    11→    Info,       // 0.3-0.5
    12→    Warning,    // 0.5-0.7
    13→    Critical,   // 0.7-0.9
    14→    Emergency,  // >0.9
    15→}
    16→
    17→impl AlertSeverity {
    18→    pub fn from_confidence(confidence: f64) -> Self {
    19→        match confidence {
    20→            c if c > 0.9 => AlertSeverity::Emergency,
    21→            c if c > 0.7 => AlertSeverity::Critical,
    22→            c if c > 0.5 => AlertSeverity::Warning,
    23→            _ => AlertSeverity::Info,
    24→        }
    25→    }
    26→
    27→    pub fn to_string(&self) -> &'static str {
    28→        match self {
    29→            AlertSeverity::Info => "INFO",
    30→            AlertSeverity::Warning => "WARNING",
    31→            AlertSeverity::Critical => "CRITICAL",
    32→            AlertSeverity::Emergency => "EMERGENCY",
    33→        }
    34→    }
    35→}
    36→
    37→// ========== Response Actions ==========
    38→
    39→#[derive(Clone, Debug)]
    40→pub enum ResponseAction {
    41→    IsolatePid(u32),              // SIGSTOP
    42→    KillPid(u32),                 // SIGKILL
    43→    Alert(AlertSeverity, String), // 알림
    44→    IncreaseSampling(u32),        // 샘플링 증가
    45→    SnapshotMemory(u32),          // 메모리 스냅샷
    46→    UpdateNNWeights,              // 모델 업데이트
    47→    EnableAudit(u32),             // 감시 활성화
    48→}
    49→
    50→// ========== Security Policy ==========
    51→
    52→pub enum SecurityPolicy {
    53→    Permissive,    // 알림만 (confidence > 0.5)
    54→    Standard,      // 격리 (confidence > 0.7)
    55→    Strict,        // 종료 (confidence > 0.8)
    56→    Emergency,     // 즉시 종료 (confidence > 0.9)
    57→}
    58→
    59→impl SecurityPolicy {
    60→    pub fn get_response(&self, threat_type: ThreatType, confidence: f64, pid: u32) 
    61→        -> Vec<ResponseAction> {
    62→        let mut actions = Vec::new();
    63→        let severity = AlertSeverity::from_confidence(confidence);
    64→
    65→        match self {
    66→            SecurityPolicy::Permissive => {
    67→                if confidence > 0.5 {
    68→                    actions.push(ResponseAction::Alert(
    69→                        severity,
    70→                        format!("Threat detected: {:?} (confidence: {:.2})", threat_type, confidence),
    71→                    ));
    72→                }
    73→            }
    74→
    75→            SecurityPolicy::Standard => {
    76→                if confidence > 0.7 {
    77→                    actions.push(ResponseAction::IsolatePid(pid));
    78→                    actions.push(ResponseAction::Alert(
    79→                        severity,
    80→                        format!("Process isolated: {:?}", threat_type),
    81→                    ));
    82→                    actions.push(ResponseAction::IncreaseSampling(pid));
    83→                }
    84→            }
    85→
    86→            SecurityPolicy::Strict => {
    87→                if confidence > 0.8 {
    88→                    actions.push(ResponseAction::SnapshotMemory(pid));
    89→                    actions.push(ResponseAction::KillPid(pid));
    90→                    actions.push(ResponseAction::Alert(
    91→                        severity,
    92→                        format!("Process terminated: {:?}", threat_type),
    93→                    ));
    94→                }
    95→            }
    96→
    97→            SecurityPolicy::Emergency => {
    98→                if confidence > 0.9 {
    99→                    actions.push(ResponseAction::KillPid(pid));
   100→                    actions.push(ResponseAction::Alert(
   101→                        AlertSeverity::Emergency,
   102→                        format!("EMERGENCY: Process killed immediately: {:?}", threat_type),
   103→                    ));
   104→                    actions.push(ResponseAction::UpdateNNWeights);
   105→                }
   106→            }
   107→        }
   108→
   109→        actions
   110→    }
   111→}
   112→
   113→// ========== Response Engine ==========
   114→
   115→pub struct ResponseEngine {
   116→    pub current_policy: SecurityPolicy,
   117→    pub response_history: Vec<(u32, String, f64)>,  // (pid, action, timestamp_ratio)
   118→    pub max_history: usize,
   119→    pub false_positive_count: u32,
   120→    pub true_positive_count: u32,
   121→}
   122→
   123→impl ResponseEngine {
   124→    pub fn new(policy: SecurityPolicy) -> Self {
   125→        Self {
   126→            current_policy: policy,
   127→            response_history: Vec::new(),
   128→            max_history: 1000,
   129→            false_positive_count: 0,
   130→            true_positive_count: 0,
   131→        }
   132→    }
   133→
   134→    pub fn respond(&mut self, result: &ClassificationResult, pid: u32) -> Vec<ResponseAction> {
   135→        let actions = self.current_policy.get_response(result.threat_type, result.confidence, pid);
   136→
   137→        // 이력 기록
   138→        for action in &actions {
   139→            let action_str = match action {
   140→                ResponseAction::IsolatePid(_) => "ISOLATE",
   141→                ResponseAction::KillPid(_) => "KILL",
   142→                ResponseAction::Alert(severity, _) => severity.to_string(),
   143→                ResponseAction::IncreaseSampling(_) => "SAMPLE",
   144→                ResponseAction::SnapshotMemory(_) => "SNAPSHOT",
   145→                ResponseAction::UpdateNNWeights => "UPDATE_NN",
   146→                ResponseAction::EnableAudit(_) => "AUDIT",
   147→            };
   148→
   149→            self.response_history.push((pid, action_str.to_string(), result.confidence));
   150→            if self.response_history.len() > self.max_history {
   151→                self.response_history.remove(0);
   152→            }
   153→        }
   154→
   155→        // 정확도 추적
   156→        if result.confidence > 0.7 {
   157→            self.true_positive_count += 1;
   158→        } else {
   159→            self.false_positive_count += 1;
   160→        }
   161→
   162→        actions
   163→    }
   164→
   165→    pub fn set_policy(&mut self, policy: SecurityPolicy) {
   166→        self.current_policy = policy;
   167→    }
   168→
   169→    pub fn get_response_latency(&self) -> f64 {
   170→        1.0  // < 1µs (mock)
   171→    }
   172→
   173→    pub fn get_false_positive_rate(&self) -> f64 {
   174→        let total = self.false_positive_count + self.true_positive_count;
   175→        if total == 0 {
   176→            0.0
   177→        } else {
   178→            self.false_positive_count as f64 / total as f64
   179→        }
   180→    }
   181→
   182→    pub fn get_accuracy(&self) -> f64 {
   183→        let total = self.false_positive_count + self.true_positive_count;
   184→        if total == 0 {
   185→            0.0
   186→        } else {
   187→            self.true_positive_count as f64 / total as f64
   188→        }
   189→    }
   190→
   191→    pub fn recover_from_false_positive(&mut self, pid: u32) {
