   191→
   192→impl AiWatchdog {
   193→    pub fn new() -> Self {
   194→        AiWatchdog {
   195→            current_metrics: PerformanceMetrics::new(),
   196→            previous_metrics: PerformanceMetrics::new(),
   197→            dvfs_state: DvfsState::P1,  // 기본: P1 (1.5GHz)
   198→            dvfs_changes: 0,
   199→            thermal: ThermalState::new(),
   200→            autonomous_decisions: 0,
   201→            total_decisions: 0,
   202→            improvement_pct: 0.0,
   203→            monitoring_cycles: 0,
   204→            last_action_ns: 0,
   205→        }
   206→    }
   207→
   208→    /// 성능 지표 업데이트
   209→    pub fn update_metrics(&mut self, metrics: PerformanceMetrics) -> bool {
   210→        if !metrics.validate() {
   211→            return false;
   212→        }
   213→
   214→        self.previous_metrics = self.current_metrics.clone();
   215→        self.current_metrics = metrics.clone();
   216→
   217→        // 온도 업데이트
   218→        self.thermal.update_temp(metrics.thermal_temp_c);
   219→
   220→        true
   221→    }
   222→
   223→    /// 성능 개선률 계산
   224→    pub fn calculate_improvement(&self) -> f32 {
   225→        let prev_score = self.previous_metrics.latency_us +
   226→                        (self.previous_metrics.power_mw / 500.0) -
   227→                        (self.previous_metrics.throughput / 10000.0);
   228→
   229→        let curr_score = self.current_metrics.latency_us +
   230→                        (self.current_metrics.power_mw / 500.0) -
   231→                        (self.current_metrics.throughput / 10000.0);
   232→
   233→        if prev_score == 0.0 {
   234→            return 0.0;
   235→        }
   236→
   237→        ((prev_score - curr_score) / prev_score) * 100.0
   238→    }
   239→
   240→    /// 자율적 최적화 결정 (L0NN 기반)
   241→    pub fn make_autonomous_decision(&mut self) -> DvfsState {
   242→        self.total_decisions += 1;
   243→        self.monitoring_cycles += 1;
   244→
   245→        // 현재 메트릭을 특성 벡터로 변환
