    80→
    81→    pub fn with_args(mut self, args: &str) -> Self {
    82→        let bytes = args.as_bytes();
    83→        for (i, &b) in bytes.iter().enumerate() {
    84→            if i >= 128 {
    85→                break;
    86→            }
    87→            self.args[i] = b;
    88→        }
    89→        self.arg_count = bytes.len().min(128) as u8;
    90→        self
    91→    }
    92→}
