     2→// 부동소수점 오차 없는 3차 방정식 솔버 + 벡터 곡선 계산
     3→
     4→module math
     5→
     6→// ============ Fixed-Point Arithmetic (Q16.16 format) ============
     7→// 정수 부분: 16bit, 소수 부분: 16bit
     8→// 범위: -32768.0 ~ 32767.99998 (±0.00001526 정밀도)
     9→
    10→struct FixedPoint {
    11→    raw: i32,  // 실제 저장값 (부호 있는 정수)
    12→}
    13→
    14→impl FixedPoint {
    15→    // 상수들
    16→    fn ZERO() -> FixedPoint { return FixedPoint { raw: 0 } }
    17→    fn ONE() -> FixedPoint { return FixedPoint { raw: 65536 } }  // 2^16
    18→    fn HALF() -> FixedPoint { return FixedPoint { raw: 32768 } }
    19→
    20→    // 정수 → Fixed-point 변환
    21→    fn from_int(n: i32) -> FixedPoint {
    22→        return FixedPoint { raw: n * 65536 }
    23→    }
    24→
    25→    // Fixed-point → 정수 (truncate)
    26→    fn to_int(&self) -> i32 {
    27→        return self.raw >> 16
    28→    }
    29→
    30→    // 부동소수점 → Fixed-point (근사)
    31→    fn from_f64_approx(f: f64) -> FixedPoint {
    32→        // 실제로는 f64를 Q16.16으로 변환
    33→        // 여기서는 간략적 표현
    34→        let int_part = f as i32
    35→        let frac = f - (int_part as f64)
    36→        let frac_bits = (frac * 65536.0) as i32
    37→
    38→        return FixedPoint { raw: (int_part << 16) + frac_bits }
    39→    }
    40→
    41→    // ============ 사칙연산 (오버플로우 안전) ============
    42→
    43→    fn add(&self, other: FixedPoint) -> FixedPoint {
    44→        return FixedPoint { raw: self.raw + other.raw }
    45→    }
    46→
    47→    fn sub(&self, other: FixedPoint) -> FixedPoint {
    48→        return FixedPoint { raw: self.raw - other.raw }
    49→    }
    50→
    51→    // 곱셈: (a/2^16) * (b/2^16) = (a*b)/2^32 → 다시 2^16으로 조정
    52→    fn mul(&self, other: FixedPoint) -> FixedPoint {
    53→        let product = ((self.raw as i64) * (other.raw as i64)) >> 16
    54→        return FixedPoint { raw: product as i32 }
    55→    }
    56→
    57→    // 나눗셈: (a/2^16) / (b/2^16) = a/b
    58→    fn div(&self, other: FixedPoint) -> FixedPoint {
    59→        if other.raw == 0 {
    60→            return FixedPoint::ZERO()  // 0으로 나누기 방지
    61→        }
    62→        let quotient = ((self.raw as i64) << 16) / (other.raw as i64)
    63→        return FixedPoint { raw: quotient as i32 }
    64→    }
    65→
    66→    // 제곱근 (Newton-Raphson)
    67→    fn sqrt(&self) -> FixedPoint {
    68→        if self.raw <= 0 {
    69→            return FixedPoint::ZERO()
    70→        }
    71→
    72→        // 초기값: x0 = (n + 2^16) / 2
    73→        let mut x = FixedPoint { raw: (self.raw + 65536) >> 1 }
    74→
    75→        // 5번 반복 (수렴 충분)
    76→        for _i in 0..5 {
    77→            let half = FixedPoint::HALF()
    78→            let term = self.div(x)
    79→            x = (x.add(term)).mul(half)
    80→        }
    81→
    82→        return x
    83→    }
    84→
    85→    // 절댓값
    86→    fn abs(&self) -> FixedPoint {
    87→        if self.raw < 0 {
    88→            return FixedPoint { raw: -self.raw }
    89→        }
    90→        return FixedPoint { raw: self.raw }
    91→    }
    92→
    93→    // 부호 (-1, 0, 1)
    94→    fn sign(&self) -> i32 {
    95→        if self.raw > 0 { return 1 }
    96→        if self.raw < 0 { return -1 }
    97→        return 0
    98→    }
    99→}
