   101→// ============ 2D 벡터 (Fixed-point) ============
   102→
   103→struct Vec2FP {
   104→    x: FixedPoint,
   105→    y: FixedPoint,
   106→}
   107→
   108→impl Vec2FP {
   109→    fn new(x: FixedPoint, y: FixedPoint) -> Vec2FP {
   110→        return Vec2FP { x: x, y: y }
   111→    }
   112→
   113→    fn add(&self, other: Vec2FP) -> Vec2FP {
   114→        return Vec2FP::new(self.x.add(other.x), self.y.add(other.y))
   115→    }
   116→
   117→    fn sub(&self, other: Vec2FP) -> Vec2FP {
   118→        return Vec2FP::new(self.x.sub(other.x), self.y.sub(other.y))
   119→    }
   120→
   121→    fn scale(&self, s: FixedPoint) -> Vec2FP {
   122→        return Vec2FP::new(self.x.mul(s), self.y.mul(s))
   123→    }
   124→
   125→    fn dot(&self, other: Vec2FP) -> FixedPoint {
   126→        return self.x.mul(other.x).add(self.y.mul(other.y))
   127→    }
   128→
   129→    fn length_sq(&self) -> FixedPoint {
   130→        return self.dot(*self)
   131→    }
   132→
   133→    fn length(&self) -> FixedPoint {
   134→        return self.length_sq().sqrt()
   135→    }
   136→}
   137→
   138→// ============ 2차 Bézier 곡선 (Quadratic) ============
   139→
   140→struct QuadraticBezier {
   141→    p0: Vec2FP,  // 시작점
   142→    p1: Vec2FP,  // 제어점
   143→    p2: Vec2FP,  // 끝점
   144→}
   145→
   146→impl QuadraticBezier {
   147→    fn new(p0: Vec2FP, p1: Vec2FP, p2: Vec2FP) -> QuadraticBezier {
   148→        return QuadraticBezier { p0: p0, p1: p1, p2: p2 }
   149→    }
   150→
   151→    // B(t) = (1-t)²P0 + 2(1-t)tP1 + t²P2, t ∈ [0,1]
   152→    fn evaluate(&self, t: FixedPoint) -> Vec2FP {
   153→        let one = FixedPoint::ONE()
   154→        let two = FixedPoint::from_int(2)
   155→
   156→        let one_minus_t = one.sub(t)
   157→        let t_sq = t.mul(t)
   158→        let one_minus_t_sq = one_minus_t.mul(one_minus_t)
   159→
   160→        let w0 = one_minus_t_sq  // (1-t)²
   161→        let w1 = two.mul(one_minus_t).mul(t)  // 2(1-t)t
   162→        let w2 = t_sq  // t²
   163→
   164→        let term0 = self.p0.scale(w0)
   165→        let term1 = self.p1.scale(w1)
   166→        let term2 = self.p2.scale(w2)
   167→
   168→        return term0.add(term1).add(term2)
   169→    }
   170→
   171→    // B'(t) = 2(1-t)(P1-P0) + 2t(P2-P1)
   172→    fn derivative(&self, t: FixedPoint) -> Vec2FP {
   173→        let one = FixedPoint::ONE()
   174→        let two = FixedPoint::from_int(2)
   175→
   176→        let one_minus_t = one.sub(t)
   177→
   178→        let dp0 = self.p1.sub(self.p0)  // P1 - P0
   179→        let dp1 = self.p2.sub(self.p1)  // P2 - P1
   180→
   181→        let term0 = dp0.scale(one_minus_t).scale(two)
   182→        let term1 = dp1.scale(t).scale(two)
   183→
   184→        return term0.add(term1)
   185→    }
   186→}
