   188→// ============ 3차 방정식 솔버 (Cubic Equation) ============
   189→// ax³ + bx² + cx + d = 0
   190→
   191→struct CubicSolver {
   192→    a: FixedPoint,
   193→    b: FixedPoint,
   194→    c: FixedPoint,
   195→    d: FixedPoint,
   196→    roots: array[FixedPoint; 3],
   197→    root_count: u32,
   198→}
   199→
   200→impl CubicSolver {
   201→    fn new(a: FixedPoint, b: FixedPoint, c: FixedPoint, d: FixedPoint) -> CubicSolver {
   202→        return CubicSolver {
   203→            a: a,
   204→            b: b,
   205→            c: c,
   206→            d: d,
   207→            roots: array[FixedPoint; 3],
   208→            root_count: 0,
   209→        }
   210→    }
   211→
   212→    fn solve(&mut self) -> bool {
   213→        // 3차 방정식을 정규화: x³ + px + q = 0 형태로
   214→        // (a = 1로 정규화)
   215→
   216→        if self.a.raw == 0 {
   217→            // 2차 방정식으로 퇴화
   218→            return self.solve_quadratic()
   219→        }
   220→
   221→        let one = FixedPoint::ONE()
   222→        let a_inv = one.div(self.a)
   223→
   224→        // 정규화 계수
   225→        let b_norm = self.b.mul(a_inv)
   226→        let c_norm = self.c.mul(a_inv)
   227→        let d_norm = self.d.mul(a_inv)
   228→
   229→        // Cardano 공식 (복잡함, 여기서는 Newton-Raphson 사용)
   230→        return self.solve_newton_raphson()
   231→    }
   232→
   233→    fn solve_newton_raphson(&mut self) -> bool {
   234→        // 초기값: t = 0.5 (정규화된 범위)
   235→        let mut t = FixedPoint::HALF()
   236→        let zero = FixedPoint::ZERO()
   237→        let one = FixedPoint::ONE()
   238→        let two = FixedPoint::from_int(2)
   239→        let three = FixedPoint::from_int(3)
   240→
   241→        // 10번 반복 (충분한 수렴)
   242→        for _i in 0..10 {
   243→            let t_sq = t.mul(t)
   244→            let t_cu = t_sq.mul(t)
   245→
   246→            // f(t) = at³ + bt² + ct + d
   247→            let f = self.a.mul(t_cu)
   248→                .add(self.b.mul(t_sq))
   249→                .add(self.c.mul(t))
   250→                .add(self.d)
   251→
   252→            // f'(t) = 3at² + 2bt + c
   253→            let f_prime = three.mul(self.a).mul(t_sq)
   254→                .add(two.mul(self.b).mul(t))
   255→                .add(self.c)
   256→
   257→            if f_prime.raw == 0 {
   258→                break  // 미분값이 0이면 수렴 불가
   259→            }
   260→
   261→            let t_next = t.sub(f.div(f_prime))
   262→
   263→            // 수렴 체크: |t_next - t| < epsilon
   264→            let delta = t_next.sub(t).abs()
   265→            if delta.raw < 100 {  // 아주 작은 오차
   266→                t = t_next
   267→                break
   268→            }
   269→
   270→            t = t_next
   271→        }
   272→
   273→        // [0, 1] 범위 확인
   274→        if t.raw >= 0 && t.raw <= one.raw {
   275→            self.roots[0] = t
   276→            self.root_count = 1
   277→            return true
   278→        }
   279→
   280→        return false
   281→    }
   282→
   283→    fn solve_quadratic(&mut self) -> bool {
   284→        // bx² + cx + d = 0
   285→        // x = (-c ± √(c² - 4bd)) / 2b
   286→
   287→        let zero = FixedPoint::ZERO()
   288→        let two = FixedPoint::from_int(2)
   289→        let four = FixedPoint::from_int(4)
   290→
   291→        if self.b.raw == 0 {
   292→            return false  // 1차도 아님
   293→        }
   294→
   295→        let discriminant = self.c.mul(self.c).sub(four.mul(self.b).mul(self.d))
   296→
   297→        if discriminant.raw < 0 {
   298→            return false  // 실근 없음
   299→        }
   300→
   301→        let sqrt_disc = discriminant.sqrt()
   302→        let denominator = two.mul(self.b)
   303→
   304→        let x1 = (zero.sub(self.c).add(sqrt_disc)).div(denominator)
   305→        let x2 = (zero.sub(self.c).sub(sqrt_disc)).div(denominator)
   306→
   307→        self.roots[0] = x1
   308→        self.roots[1] = x2
   309→        self.root_count = 2
   310→
   311→        return true
   312→    }
   313→
   314→    fn get_roots(&self) -> array[FixedPoint; 3] {
   315→        return self.roots
   316→    }
   317→
   318→    fn get_root_count(&self) -> u32 {
   319→        return self.root_count
   320→    }
   321→}
   322→
   323→// ============ 거리 계산 (Bézier → 최단거리) ============
   324→
   325→struct BezierDistance {
   326→    curve: QuadraticBezier,
   327→    point: Vec2FP,
   328→}
   329→
   330→impl BezierDistance {
   331→    fn new(curve: QuadraticBezier, point: Vec2FP) -> BezierDistance {
   332→        return BezierDistance { curve: curve, point: point }
   333→    }
   334→
   335→    fn compute(&self) -> FixedPoint {
   336→        // 점 P에서 곡선 B(t)까지의 최단거리 찾기
   337→        // |P - B(t)|² 를 최소화하는 t 찾기
   338→
   339→        let mut min_dist = FixedPoint::from_int(999999)
   340→        let step = FixedPoint::from_int(1).div(FixedPoint::from_int(100))  // 0.01 단위로 샘플링
   341→        let mut t = FixedPoint::ZERO()
   342→        let one = FixedPoint::ONE()
   343→
   344→        // 샘플링으로 대략적인 최소값 찾기
   345→        while t.raw <= one.raw {
   346→            let pt = self.curve.evaluate(t)
   347→            let diff = pt.sub(self.point)
   348→            let dist = diff.length()
   349→
   350→            if dist.raw < min_dist.raw {
   351→                min_dist = dist
   352→            }
   353→
   354→            t = t.add(step)
   355→        }
   356→
   357→        return min_dist
   358→    }
   359→}
