   362→
   363→fn validate_fixed_point() -> bool {
   364→    let zero = FixedPoint::ZERO()
   365→    let one = FixedPoint::ONE()
   366→    let half = FixedPoint::HALF()
   367→
   368→    assert(zero.raw == 0, "zero correct")
   369→    assert(one.raw == 65536, "one correct")
   370→    assert(half.raw == 32768, "half correct")
   371→
   372→    let sum = one.add(one)
   373→    assert(sum.raw == 131072, "1+1=2")
   374→
   375→    let product = half.mul(half)
   376→    assert(product.to_int() == 0, "0.5*0.5=0.25 (truncated to 0)")
   377→
   378→    return true
