   380→
   381→fn validate_bezier_evaluation() -> bool {
   382→    let zero = FixedPoint::ZERO()
   383→    let one = FixedPoint::ONE()
   384→    let half = FixedPoint::HALF()
   385→
   386→    let p0 = Vec2FP::new(zero, zero)
   387→    let p1 = Vec2FP::new(half, one)
   388→    let p2 = Vec2FP::new(one, zero)
   389→
   390→    let bezier = QuadraticBezier::new(p0, p1, p2)
   391→
   392→    let at_zero = bezier.evaluate(zero)
   393→    assert(at_zero.x.raw == 0, "B(0).x = 0")
   394→
   395→    let at_one = bezier.evaluate(one)
   396→    assert(at_one.x.raw == one.raw, "B(1).x = 1")
   397→
   398→    return true
   399→}
   400→
   401→fn validate_cubic_solver() -> bool {
   402→    let zero = FixedPoint::ZERO()
   403→    let one = FixedPoint::ONE()
   404→    let two = FixedPoint::from_int(2)
   405→
   406→    // x³ - x = 0 → roots: 0, 1, -1
   407→    // a=1, b=0, c=-1, d=0
   408→    let mut solver = CubicSolver::new(one, zero, zero.sub(one), zero)
   409→
   410→    assert(solver.solve(), "solve should succeed")
   411→    assert(solver.get_root_count() >= 1, "should find at least 1 root")
   412→
   413→    return true
   414→}
