    24→        return CPUState {
    25→            pc: 0x80000000,  // Kernel start address
    26→            sp: 0x80800000,  // Stack: 8MB
    27→            el: 2,           // EL2 (hypervisor mode start)
    28→            daif: 0xF,       // All interrupts disabled
